window.ANTZ_I18N = {"meta":{"lang":"et","source":false,"reviewed":false,"translator":"machine (Claude)"},"ui":{"brand.title":"Antz sissejuhatav juhend","brand.label":"Sissejuhatav juhend","brand.home":"Antz Systems, avaleht","meta.description":"Lühike ja näitlik juhend Antzi platvormi kohta loomahoolduse meeskondadele.","nav.primary":"Põhimenüü","nav.menu":"Menüü","nav.modules":"Moodulid","nav.why":"Miks Antz","nav.start":"Alustamine","nav.faq":"KKK","nav.search":"Otsi juhendist","nav.searchTip":"Otsing (Ctrl/Cmd + K)","footer.tagline":"Head andmed = head teadmised = terved loomad","footer.explore":"Tutvu","footer.talk":"Võtke meiega ühendust","footer.rights":"© 2026 Antz Systems. Kõik õigused kaitstud.","lang.label":"Keel","lang.note":"See leht on masintõlgitud ja ootab emakeelse kõneleja ülevaatust.","lang.english":"Vaata inglise keeles","lang.dismiss":"Sulge","lang.inApp":"Rakenduses: {x}","hero.title":"Üks platvorm kõigile Teie hoole all olevatele loomadele","hero.sub":"Andmed, igapäevatöö ja meeskonnatöö kõigis Teie asukohtades. Leidke Antzis iga toiming koos päris ekraanivaadetega.","hero.areas":"{n} töövaldkonda","hero.devices":"Mobiil ja veeb","search.label":"Otsi mooduleid ja funktsioone","search.cue":"Otsi: {x}","search.clear":"Tühjenda otsing","search.short":"Sisestage vähemalt kaks tähte, et otsida kõigist moodulitest ja funktsioonidest.","search.top":"Parimad tulemused","search.none":"Päringule „{q}“ vasteid ei leitud. Proovige „loom“, „muna“ või „aruanne“.","start.label":"Alusta siit","kit.objective.eyebrow":"Alusta siit","kit.objective.more":"Loe eesmärki","kit.objective.kicker":"Miks me seda koolitust korraldame","kit.objective.photo":"Loomahoidja toidab väikest looma tema aedikus","kit.platform.eyebrow":"Platvorm","kit.platform.more":"Lisateave Antzi kohta","kit.platform.why":"Miks seda rakendust kasutada","kit.platform.photo":"Käsi hoiab telefoni, millel on avatud Antz Systemsi rakendus","kit.start.eyebrow":"Sisseelamise käik","kit.start.more":"Alusta juhendiga","kit.start.features":"Funktsioonid","day.title":"Milline on Teie esimene päev Antzis","day.lede":"Neli sammu viivad meeskonna esimesest sisselogimisest igapäevase kasutuseni.","day.1":"Logige oma tööruumi sisse","day.2":"Tutvuge liidesega","day.3":"Seadistage põhiandmed","day.4":"Andke igaühele õiged juurdepääsuõigused","day.4.desc":"Looge organisatsioonile vastavad rollid ja lülitage õigused sisse mooduli kaupa, nii et igaüks näeb seda, mida tema töö vajab.","modules.eyebrow":"Mis on sees","modules.title":"Tutvuge moodulitega","modules.lede":"Puudutage mis tahes kaarti, et avada selle juhend koos kõigi funktsioonide ja ekraanivaadetega.","modules.filter":"Filtreeri mooduleid valdkonna järgi","modules.all":"Kõik","modules.count":"{n} moodulit","modules.features":"{n} funktsiooni","spot.tag":"Esiletõstetud töövoog","spot.link":"Vaata lähemalt: {x}","cta.title":"Jäite mõne toiminguga hätta?","cta.text":"Selles juhendis on iga mooduli funktsioonid ja päris ekraanivaated. Jätkake sealt, kus pooleli jäite, või küsige meilt ja me aitame.","cta.back":"Tagasi moodulite juurde","cta.or":"Küsimusi? Kirjutage aadressile {email}","faq.eyebrow":"KKK","faq.title":"Küsimused, mida meeskonnad esimesena küsivad","faq.q1":"Mis on Antz?","faq.q2":"Kas see töötab telefonis ja arvutis?","faq.a2":"Jah. Mobiilirakendus katab välitöö, näiteks märkmed, ravi, üleviimised ja munade andmed. Veebirakendus katab lauatöö, näiteks haiglasüsteemi, kasvanduse seadistuse, aruanded ja apteegi varud. Muudatused ilmuvad reaalajas telefonis, tahvelarvutis ja lauaarvutis.","faq.q3":"Kas saame määrata, kes mida näeb?","faq.a3":"Jah. Juurdepääs on rollipõhine. Loote organisatsioonis kasutatavad rollid, näiteks Zooloog, ja lülitate õigused sisse mooduli kaupa.","faq.q4":"Meil on mitu asukohta. Kas see sobib?","faq.a4":"Antz hoiab kõigi asukohtade ja osakondade andmeid ühes kohas. Paigutus on korraldatud asukoha, sektsiooni ja aediku kaupa ning asukohtadevahelised üleviimised läbivad kinnitamise ja turvakontrolliga väljaregistreerimise.","faq.q5":"Kuidas alustada?","faq.a5":"Alustage juhendist „Alustamine“ ja avage seejärel moodulid, mida Teie roll kasutab. Kui midagi jääb ebaselgeks, kirjutage aadressile hello@antz.systems.","pager.prev":"Eelmine","pager.next":"Järgmine","pager.modules":"Tutvuge moodulitega","pager.pages":"Eelmine ja järgmine leht","pager.moduleNav":"Eelmine ja järgmine moodul","mod.tabs":"Moodulite valdkonnad ja moodulid","mod.features":"Funktsioonid","mod.hintClick":"Klõpsake funktsioonil, et avada selle ekraanivaade","mod.hintTap":"Puudutage funktsiooni, et avada selle ekraanivaade","mod.soon":"Selle mooduli ekraanivaated lisanduvad peagi","mod.zoom":"Suurendamiseks puudutage ekraanivaadet","win.prev":"Eelmine funktsioon","win.next":"Järgmine funktsioon","win.close":"Sulge","win.count":"Funktsioon {i}/{n}","win.soon":"Ekraanivaade lisandub peagi","gal.label":"Ekraanivaated: {x}","gal.close":"Sulge galerii","gal.screen":"Ekraanivaade {i}","gal.hint":"Suurendamiseks liigutage sõrmi lahku või topeltpuudutage · Sirvimiseks pühkige"},"tracks":{"records":{"label":"Andmed ja suhtlus","desc":"Kõige kergemad ja sagedamini kasutatavad vaated: märkmed, vestlus ja kasutajate seadistus."},"animal":{"label":"Loomade andmed ja liikumine","desc":"Kollektsioon, paigutus ja iga looma liikumine loomaaias."},"medical":{"label":"Meditsiin ja ravi","desc":"Terviseandmed, retseptid, ravi ja haiglainfosüsteem."},"mortality":{"label":"Suremus ja elutsükkel","desc":"Suremuse, lahangute ja munade elutsükli haldus."},"operations":{"label":"Tegevused ja järelevalve","desc":"Teadaanded, kasutajatugi, turvalisus, aruandlus ja vastavus nõuetele."}},"modules":{"objective-of-this-kit":{"title":"Selle juhendi eesmärk","intro":"Sisseelamisel on neli ülesannet: anda igale meeskonnaliikmele kindlustunne igapäevastes tegevustes, juurutada platvorm kõigis rollides, tuvastada puudujäägid, et saaksime paremaks muutuda, ning ühtlustada andmete pidamine kõigis asukohtades.","features":[{"title":"Oskuste arendamine","desc":"Töötajate teadmiste ja praktiliste oskuste täiendamine, mida on vaja tõhusaks loomaaia tööks, loomade hoolduseks ja Antzi platvormi enesekindlaks kasutamiseks.","alt":""},{"title":"Süsteemi juurutamine","desc":"Kasutajate tutvustamine kõigi rakenduse moodulitega ja kindlustunde loomine, et põhitoiminguid, nagu andmete sisestamine, ülevaatamine ja kinnitamine, saaks teha ilma juhendamiseta.","alt":""},{"title":"Pidev täiustamine","desc":"Puudujääkide tuvastamine, küsimuste selgitamine ja tagasisidel põhinev õppimine, et töövooge ja moodulite toimimist aja jooksul täpsustada.","alt":""},{"title":"Ühtlustamine","desc":"Ühtsed protokollid kõigis meeskondades ja asukohtades ning samasugune moodulite toimimine taotluste, suremuse, munade ja toitumise puhul, nii et iga kirje on ühtmoodi loetav.","alt":""}]},"what-is-antz-systems":{"title":"Mis on Antz Systems?","intro":"Antz on terviklik platvorm loomade andmete, igapäevatöö ja meeskonnatöö jaoks. See koondab kõigi asukohtade ja osakondade andmed, nii et iga toiming on dokumenteeritud, läbipaistev ja jälgitav.","features":[{"title":"Paremad andmed, parem hooldus","desc":"Iga detail on täpne, kättesaadav, ajatempliga ja seotud õige loomaga.","alt":""},{"title":"Lihtne meeskonnatöö","desc":"Veterinaaride, hooldajate ja juhtide vahel pole lünki – kõik töötavad samade andmetega.","alt":""},{"title":"Turvaline juba ülesehituselt","desc":"Rollipõhine juurdepääs kaitseb tundlikke andmeid ja viib õigused kooskõlla organisatsiooni struktuuriga.","alt":""},{"title":"Otsused käeulatuses","desc":"Kiirem aruandlus ja nõuetele vastavad ülevaated ilma arvutustabeliteta.","alt":""},{"title":"Paberivaba töö","desc":"Vähendage ümberkirjutamise vigu ja säästke aega igas vahetuses.","alt":""},{"title":"Reaalajas värskendused","desc":"Uusim teave on alati ja kõikjal kättesaadav telefonis, tahvelarvutis ja lauaarvutis.","alt":""}],"shots":{"assets/shots/app-welcome-c.jpg":"Antz Systemsi rakenduse tervituskuva: head andmed + head teadmised = terved loomad."}},"getting-started":{"title":"Alustamine","intro":"Alustamise juhend tutvustab rakenduse eesmärki ja juhatab uued kasutajad läbi olulistest sammudest: profiili seadistamine, põhifunktsioonidega tutvumine ja platvormil tõhus liikumine.","features":[{"title":"Juurdepääs ja tööruumid","desc":"Logige turvaliselt sisse ja avage Teile määratud töökeskkond.","alt":"Antz Systemsi avakuva: otsinguriba, ootel manustamised, selle kuu ülevaade sündimuse ja suremusega ning teadaande kaart"},{"title":"Navigeerimine ja liides","desc":"Kasutage avalehe voogu värskenduste ja kiirlinkide jaoks ning alumist paneeli põhitööriistade jaoks.","alt":""},{"title":"Ootel lahang / manustamine / paigutamine","desc":"Loomad, kes ootavad lahangut, haldusdokumentide koostamist ning seejärel paigutamist või hävitamist enne andmete lõplikku sulgemist.","alt":""},{"title":"Põhiandmete seadistus ja moodulid","desc":"Seadistage põhiandmed ja tutvuge moodulitega, nagu terviseandmed, paigutus, munad, toitumine ja loomade haldus.","alt":""},{"title":"Isikupärastamine","desc":"Hallake märkmeid, uuendage oma profiili ja muutke keele-eelistusi.","alt":""},{"title":"Õigused","desc":"Saage aru, milliseid juurdepääsutasemeid on turvaliseks tööks vaja.","alt":""}]},"notes-module":{"title":"Märkmete moodul","intro":"Märkmete moodul koondab loomade, aedikute ja tegevustega seotud igapäevaste värskenduste, tähelepanekute ja vahejuhtumite kirjed. See tagab struktureeritud ja ajatempliga kirjed, sujuva meeskonnatöö ning kiire leidmise filtrite ja siltide abil ning toetab järjepidevat hooldust, probleemide varajast avastamist ja nõuetele vastavust.","summary":"Koondab loomade, aedikute ja tegevustega seotud igapäevased värskendused, tähelepanekud ja vahejuhtumid","features":[{"title":"Märkmete lisamine ja vaatamine","desc":"Looge uusi märkmeid ja vaadake enda või teiste volitatud kasutajate märkmeid.","alt":"Uue märkme vorm: märkme tüüp, märkmed, liikmete teavitamine, objekt, manused, prioriteet"},{"title":"Muutmine, kuulamine ja kustutamine","desc":"Muutke märkmeid, kuulake neid helina või eemaldage need vastavalt määratud õigustele.","alt":"Märkme üksikasjad: meditsiiniline, haige, Tiger AID 425990, muutmis- ja järjehoidjanupuga"},{"title":"Prioriteet","desc":"Määrake kiireloomulisus, et õiged inimesed näeksid märget esimesena.","alt":"Märkme üksikasjad, paremal üleval prioriteedilipp"},{"title":"Märkme tüüp ja sidumine","desc":"Liigitage märkmeid, siduge need loomade, aedikute või sektsioonidega ja lisage dokumente.","alt":"Märkme üksikasjad seotud looma kaardiga, Tiger AID 425990"},{"title":"Nähtavus","desc":"Märkmed ilmuvad automaatselt vastava looma, asukoha või sektsiooni lehele.","alt":"Asukoha lehe märkmete vahekaart: hügieenimärge asukohas Central Reserve Kingdom"},{"title":"Teavitused ja koostöö","desc":"Teavitage märgitud liikmeid; meeldimised ja kommentaarid hoiavad arutelu fookuses.","alt":"Märge pöidla üles märgiga, märgitud liige Dr. Cloomy Fernandes, 1 kommentaar"},{"title":"Filtrid ja otsing","desc":"Filtreerige märksõnade, siltide, looja või seotud objekti järgi.","alt":"Märkmete loend vahekaartidega „Minu märkmed“ / „Kõik märkmed“ (\"My Notes\" / \"All Notes\") ja filtritega"}]},"user-management":{"title":"Kasutajate haldus","intro":"Kasutajate moodul võimaldab kontode, rollide ja õiguste turvalist ja keskset haldust. See lihtsustab kasutajate lisamist, tagab andmete turvalisuse ja viib juurdepääsuõigused kooskõlla organisatsiooni rollidega, säilitades vastutuse tagamiseks üksikasjaliku tegevuslogi.","summary":"Võimaldab kontode, rollide ja õiguste turvalist ja keskset haldust","features":[{"title":"Profiili loomine ja haldus","desc":"Hallake nime, kontaktandmeid, töötaja ID-d, sünniaega ja veregruppi.","alt":"Kasutaja lisamise põhiandmete vorm: nimi, kasutajanimi, e-post, parool, mobiil, töötaja ID"},{"title":"Rollid ja õigused","desc":"Määrake rolle ja hallake juurdepääsuõigusi mooduli tasandil.","alt":"Õiguste muutmine: veterinaari roll mooduli tasandi juurdepääsu märkeruutudega"},{"title":"Juurdepääsu kontroll","desc":"Piirake asukoha/sektsiooni järgi, aktiveerige kontosid, automaatne väljalogimine.","alt":"Kasutajaprofiil menüüga: deaktiveeri, lähtesta parool, lähtesta pääsukood"},{"title":"Sisselogimine ja taastamine","desc":"Turvaline sisselogimine ja taastamine ühekordse koodiga SMS-i või WhatsAppi kaudu.","alt":"Parooli lähtestamise / unustatud parooli kuva kasutajanime või e-posti väljaga"},{"title":"Tegevuste jälgimine","desc":"Vaadake viimast sisselogimist ja seadmete andmeid ning deaktiveerige seadmeid.","alt":"Kasutajaprofiili päeviku vahekaart: tegevuslogi viimase aktiivsuse ajaga"},{"title":"Lisateave","desc":"Sisestage haridus ja töökogemus ning laadige üles isikut tõendavad dokumendid.","alt":"Kasutajaprofiili isikut tõendavate dokumentide vahekaart: Aadhaari kaart koos manusega"}]},"collection":{"title":"Kollektsioon","intro":"Kollektsiooni moodul on loodud asutuse loomakollektsiooni kõigi aspektide haldamiseks ja dokumenteerimiseks. See on keskne koht liikide registreerimiseks, üksikloomade jälgimiseks ja täpse taksonoomilise ajaloo säilitamiseks.","summary":"Asutuse loomakollektsiooni haldamine ja dokumenteerimine: liikide registreerimine, üksikloomade jälgimine ja täpne taksonoomiline ajalugu","features":[{"title":"Liikide ülevaade","desc":"Taksonoomia, arvukus soo järgi, juurdetulekute ja sündide arv ning otsing.","alt":"Tiigri liigi üksikasjad: arvukus, asukohad, sektsioonid, aedikud"},{"title":"Liikide haldus","desc":"Arvud, värvivormid, terviseandmed, toitumine, suremus ja lahangu olek.","alt":"Tiigri liigi üksikasjad: arvukus, asukohad, sektsioonid, aedikud"},{"title":"Rühmahindamise lisamine","desc":"Rühma andmete sisestamine järjestikuse liikumise ja filtritega.","alt":"Liigi hindamiste loend iga looma kehaseisundiga"}]},"housing":{"title":"Paigutus","intro":"Paigutuse moodul korraldab loomade elupaigad Teie asukohtade, sektsioonide ja aedikute kaupa, nii et iga looma asukoht on teada ja iga muudatus jälgitav. Juurdepääs igal tasandil põhineb õigustel.","summary":"Korraldab loomade elupaigad asukohtade, sektsioonide ja aedikute kaupa, nii et iga looma asukoht on teada ja iga muudatus jälgitav","features":[{"title":"Asukohtade haldus","desc":"Lisage või muutke asukohti rollipõhiste õigustega, et tagada turvaline ja struktureeritud juurdepääs.","alt":"Asukoha üksikasjad: Wildlife Zoological Park liikide, loomade ja sektsioonide arvu ning aedikute loendiga"},{"title":"Sektsioonide haldus","desc":"Lisage või muutke loomaaia sektsioone õigustel põhinevate kontrollidega, et haldus oleks turvaline.","alt":"Sektsiooni üksikasjad: Animal Kingdom liikide, loomade ja aedikute arvu ning aedikute loendiga"},{"title":"Aedikute haldus","desc":"Lisage või muutke aedikuid ja jälgige igaüht, et loomi ja andmeid tõhusalt üle vaadata.","alt":"Aedikute loend: Gentle Giants, Herbivores, The Tiger Trail koos loomade arvuga"}]},"animal-management":{"title":"Loomade haldus","intro":"Loomade moodul koondab kõik loomade andmed ühte kohta – aktiivsed, üle viidud, kadunud või kustutatud – koos profiilide, juurdetuleku töövoogude ja lihtsa vahekaartidel põhineva paigutusega.","summary":"Koondab kõik loomade andmed ühte kohta","features":[{"title":"Loomade otsing","desc":"Lisage uusi loomi juhendatud töövoogude abil, mis on seotud paigutuse, toitumise ja terviseandmetega.","alt":"Loomade loend koos arvudega: kõik loomad 2828, üle viidud 11, kustutatud 27, kadunud/põgenenud 8"},{"title":"Hiljuti lisatud","desc":"Süsteemi äsja lisatud loomad voo ülaosas.","alt":"Hiljuti lisatud loend: aeglori, savanni-elevant, tiiger, soolaveekrokodill, kiivrikasuaar"},{"title":"Kõik loomad","desc":"Täielik andmebaas, mida saab otsida, filtreerida ja eksportida.","alt":"Kõigi loomade loend: küülik, kiivrikasuaar, jõehobu, tiiger, india elevant"},{"title":"Üle viidud","desc":"Asukohtade või aedikute vahel üle viidud loomad koos täieliku päritoluga.","alt":"Üle viidud loomade loend: tiiger, lõvi, aeglori, baribal, lõvi"},{"title":"Kustutatud","desc":"Eemaldatud loomade kirjed, mida säilitatakse auditi ja taastamise võimaldamiseks.","alt":"Kustutatud loomade loend"},{"title":"Kadunud / põgenenud","desc":"Kadunuks või põgenenuks märgitud loomad, seotud vahejuhtumi aruandega.","alt":"Kadunud/põgenenud loomade loend: baribal, kiivrikasuaar, soolaveekrokodill, jõehobu, tiiger"}]},"tags-hub":{"title":"Siltide keskus","intro":"Siltide keskuse moodul aitab ANTZ-i platvormil korraldada ja liigitada erinevaid objekte (asukohad, sektsioonid, aedikud, loomad) kohandatavate siltidega, mis põhinevad nende praegusel olekul, otstarbel või mis tahes kohandatud liigitusel.","summary":"Aitab korraldada ja liigitada objekte (asukohad, sektsioonid, aedikud, loomad) kohandatavate siltidega oleku, otstarbe või kohandatud liigituse järgi","features":[{"title":"Siltide tüübid – avalik, privaatne, süsteemne","desc":"Korraldage ja liigitage objekte avalike, privaatsete ja süsteemi määratud siltidega.","alt":"Minu siltide keskus: otsing, siltide koguarv ning süsteemsete, avalike ja privaatsete siltide arv ning avalike ja privaatsete siltide kiibid"},{"title":"Otsing ja filtrid","desc":"Leidke silte kiiresti otsingu ja filtrite abil.","alt":"Minu siltide keskus: otsing, siltide koguarv ning süsteemsete, avalike ja privaatsete siltide arv ning avalike ja privaatsete siltide kiibid"},{"title":"Siltide loomine","desc":"Looge vastavalt vajadusele uusi avalikke või privaatseid silte.","alt":"Uue sildi loomine: sildi nimi, sildi kategooria, teavitatavad rollid, märkmed ja nupp „Loo silt“ (\"Create Tag\")"},{"title":"Siltide muutmine ja kustutamine","desc":"Muutke privaatsete siltide nime, värvi või nähtavust või eemaldage jäädavalt sildid, mida enam ei vajata.","alt":"Sildi üksikasjade leht: kategooria, tüüp, looja, märkmed, sildistatud objektid ning muutmise ja kustutamise toimingud"},{"title":"Avalike ja privaatsete siltide määramine","desc":"Lisage silte asukohtadele, sektsioonidele, aedikutele või loomadele, et neid oleks lihtne korraldada.","alt":"Avaliku sildi lisamise leht asukohal: otsige ja valige lisatav sildikiip, nupud „Tühista“ ja „Lisa silt“"},{"title":"Määratud siltide eemaldamine","desc":"Eemaldage silte asukohtadelt, sektsioonidelt, aedikutelt või loomadelt, kui vaja.","alt":"Sildi eemaldamise kinnitus: kas soovite need sildid sellelt asukohalt eemaldada? Tühista või eemalda"},{"title":"Nähtavus","desc":"Määrake, kas privaatsed sildid jäävad isiklikuks või on nähtavad kõigile kasutajatele.","alt":"Privaatse sildi üksikasjad: sildi tüüp privaatne (nähtav kõigile) ja lüliti „Muuda see silt kõigile nähtavaks“"},{"title":"Sildistatud objektid","desc":"Vaadake kõiki valitud sildiga seotud asukohti, sektsioone, aedikuid, liike ja loomi.","alt":"Sildi Enclosure Maintenance sildistatud objektid: vahekaardid loomad / sektsioonid / asukoht, asukoht (1) näitab Bangalore’i asukohta"}]},"animal-transfer":{"title":"Loomade üleviimine","intro":"Registreerib ja haldab kõiki loomade liikumisi organisatsiooni sees ja väljaspool, jälgides taotlusi, kinnitusi ja paigutusi, et ümberpaigutamine oleks turvaline ja hästi dokumenteeritud.","summary":"Registreerib ja haldab kõiki loomade liikumisi organisatsiooni sees ja väljaspool","features":[{"title":"Üleviimise tüübid","desc":"Asutusesisesed, asukohtadevahelised ja välised üleviimised.","alt":"Üleviimise tüübi valiku dialoog"},{"title":"Kinnitamine","desc":"Asukoha määratud vastutajate luba.","alt":"Kinnitamist ootav asukohtadevaheline üleviimine"},{"title":"Tühistamine / tagasilükkamine","desc":"Tühistage või lükake taotlusi tagasi ja algatage need vajadusel uuesti.","alt":"Üleviimise tühistamise valik"},{"title":"Turvakontrolliga sisse- ja väljaregistreerimine","desc":"Kontrollitud sisse- ja väljaregistreerimine asukohtadevaheliste ja väliste üleviimiste korral.","alt":"Üleviimise turvakontroll ja väljaregistreerimine"},{"title":"Paigutamine","desc":"Saabumisel paigutage loom aedikusse ja teavitage töötajaid.","alt":"Kinnitatud üleviimine, aedikute määramine"},{"title":"Üleviimiste logi","desc":"Täielik oleku ajalugu koos ajatemplite ja kasutajatega.","alt":"Üleviimise oleku ajatelg, üleviimine lõpetatud"}]},"approvals":{"title":"Kinnitused","intro":"Haldab ja jälgib loomade üleviimise taotlusi, andes ülevaate ootel, kinnitatud ja tagasi lükatud taotlustest. See lihtsustab ülevaatust, tagab nõuetekohase loa ning säilitab läbipaistva ülevaate üleviimisotsustest vastutuse ja nõuetele vastavuse tagamiseks.","summary":"Haldab ja jälgib loomade üleviimise taotlusi ning annab ülevaate ootel, kinnitatud ja tagasi lükatud taotlustest","features":[{"title":"Oleku jälgimine","desc":"Ootab kinnitamist, kinnitatud, tagasi lükatud, väljumine/sisenemine lubatud, paigutatud.","alt":"Üleviimiste kinnituste loend olekumärkidega"},{"title":"Taotluse ülevaatus","desc":"Vaadake enne kinnitamist kõiki üksikasju.","alt":"Ülevaatamiseks avatud üleviimistaotluse üksikasjad"},{"title":"Kinnitamine / tagasilükkamine","desc":"Andke luba või keelduge nõuetekohase põhjendusega.","alt":"Üleviimistaotluse üksikasjad nuppudega „Kinnita“ (\"Approve\") ja „Lükka tagasi“ (\"Reject\")"},{"title":"Kinnituse lähtestamine","desc":"Avage uuesti või uuendage varem kinnitatud taotlust.","alt":"Kinnitatud üleviimine kinnituse lähtestamise valikuga"},{"title":"Üleviimise tühistamine","desc":"Tühistage enne või pärast kinnitamist, põhjus salvestatakse.","alt":"Taotluse üksikasjad üleviimise tühistamise valikuga"}]},"missing-escaped-animal":{"title":"Kadunud / põgenenud loom","intro":"Võimaldab kiiresti teatada kadunud või põgenenud loomadest, neid jälgida ja juhtumeid lahendada. Ajatempliga kirjed on seotud loomade profiilidega, mis tagab vastutuse ning turva-, veterinaar- ja juhtimismeeskondade koordineeritud tegutsemise.","summary":"Võimaldab kiiresti teatada kadunud või põgenenud loomadest, neid jälgida ja juhtumeid lahendada","features":[{"title":"Vahejuhtumist teatamine ja manused","desc":"Sisestage üksikasjad ja tegevused ning laadige üles pilte või videoid.","alt":"Põgenenud/kadunud loomadest teatamise vorm"},{"title":"Aruande muutmine","desc":"Uuendage või muutke vahejuhtumi aruannet olukorra arenedes.","alt":"Vahejuhtumi ajatelg, loom kadunud"},{"title":"Leidmisest teatamine","desc":"Sisestage leidmise üksikasjad ja märkige parandused.","alt":"Leitud loomast teatamise vorm"},{"title":"Sündmuste logimine ja jälgitavus","desc":"Salvestage iga tegevus järjekorras looma ajateljele.","alt":"Menüü valikuga märkida kadumisteade ekslikuks"},{"title":"Nähtavus","desc":"Profiilil on märge „kadunud“; kiired uuendused QR-koodi abil.","alt":"Looma profiil kadunud looma märgi ja QR-koodiga"}]},"medical-records":{"title":"Terviseandmed","intro":"Meditsiinimoodul aitab registreerida, jälgida ja hallata loomade terviseandmeid, sealhulgas diagnoose, retsepte ja ravi. See toetab õigeaegset hooldust, korrastatud haiguslugu ja veterinaarmeeskondade koostööd loomade parema heaolu nimel.","summary":"Aitab registreerida, jälgida ja hallata loomade terviseandmeid","features":[{"title":"Kirje loomine","desc":"Mitu töövoogu üksik-, partii-, rühma-, plaaniliste (vaktsineerimine, ussitõrje, lisandid) või otseste (manustamine, retsept, vaktsineerimine, ussitõrje, lisandid) kirjete lisamiseks koos täpse kuupäeva ja kellaaja ning laboritaotlustega.","alt":"Kirje loomise menüü: üksik-, rühma- ja partii tervisekirje, ühendatud laboritaotlus, otsene manustamine, retsept, vaktsineerimine, ussitõrje, lisandid"},{"title":"Kirje ülevaade","desc":"Kiire kokkuvõte arsti andmete ja looma profiiliga, et teave oleks hõlpsasti leitav.","alt":"Tervisekirje ülevaade MED-09501: arst, looma profiil, juhtumi tüüp ja sümptomid"},{"title":"Järjehoidja, muutmine, kustutamine, allalaadimine","desc":"Muutke või eemaldage kirjeid; allalaaditud aruanded saadetakse registreeritud e-posti aadressile.","alt":"Tervisekirje MED-08805 järjehoidja-, muutmis- ja lisavalikute ikoonidega"},{"title":"Terviseandmete päeviku ajatelg","desc":"Kõigi lisamis- ja muutmistoimingute kronoloogiline logi koos täieliku jälgitavusega.","alt":"Terviseandmete päevik: tervisekirjete toimingute kronoloogiline logi ajatemplitega"},{"title":"Kirjete ümbermääramine","desc":"Muutmisõigustega arstid saavad teise veterinaari loodud kirjed endale ümber määrata.","alt":"Ümbermääramise kinnitus: kas soovite selle tervisekirje endale ümber määrata? Jah / Ei"}]},"symptoms-clinical-assessment-prescription":{"title":"Sümptomid, kliiniline hindamine ja retsept","intro":"Funktsioon „Sümptomid, kliiniline hindamine ja retsept“ annab ülevaate registreeritud sümptomitest, diagnoosidest ja määratud ravist, aidates kasutajatel jälgida tervisesuundumusi ja toetades teadlike kliiniliste otsuste tegemist.","summary":"Annab ülevaate registreeritud sümptomitest, diagnoosidest ja määratud ravist, et jälgida tervisesuundumusi ja toetada kliinilisi otsuseid","features":[{"title":"Sümptomite suundumused","desc":"Analüüsige liikide lõikes kõige sagedamini registreeritud sümptomeid ja jälgige sümptomite esinemist ajas.","alt":"Sümptomite analüüs: 7 liiki, 7 sümptomite järgi, pingerida eesotsas ebanormaalse väljaheite, ebanormaalse kehahoiaku ja ebanormaalse kestumisega"},{"title":"Kliinilise hindamise ülevaade","desc":"Jälgige loomadel tehtud kliinilisi hindamisi ja tuvastage kõige sagedamini registreeritud diagnoosid või seisundid.","alt":"Kliinilise hindamise analüüs: 20 liiki, 35 hindamist, eesotsas maksahaigus, hambakaaries ja seedetrakti probleemid"},{"title":"Retseptide analüüs","desc":"Vaadake sageli määratud ravimeid ja ravimustreid liikide ja juhtumite lõikes.","alt":"Retseptide analüüs: 7 liiki, 7 retsepti, eesotsas Aculife, Fluvac Innovator, Dolo 650"},{"title":"Filtrid ja otsing","desc":"Täpsustage andmeid kuupäevavahemiku, asukoha, liigi ja muude asjakohaste kriteeriumide järgi.","alt":"Filtreerimine kuupäevavahemiku järgi: täna, eile, viimased 7 päeva, see kuu, viimased 3 kuud, viimased 6 kuud, kõik andmed"}]},"administer-medicine":{"title":"Ravimite manustamine","intro":"Manustamise moodul täiendab terviseandmeid, muutes retseptid rakendatavateks ravitöövoogudeks ja võimaldades reaalajas ravi üksikloomadele või loomarühmadele nii välitingimustes kui ka haiglas.","summary":"Täiendab terviseandmeid, muutes retseptid rakendatavateks ravitöövoogudeks","features":[{"title":"Kiirsisestus","desc":"Looge valitud kuupäevaks otsene manustamiskirje ilma täielikku tervisekirjet koostamata.","alt":"Manustamise kuva: kuupäevariba, looma- ja rühmakirjete vahekaardid, olekupaanid „manustatud“, „vahele jäetud“, „lõpetatud“, „ootel“, esile tõstetud kiirsisestuse plussnupp"},{"title":"Otsing ja filtrid","desc":"Leidke kirjed kiiresti ja kitsendage loendit kuupäeva, objekti, liigi või kontrollitava aine järgi.","alt":"Manustamise kuva, esile tõstetud otsing, filtrid, kuuvalija ja rippmenüü „Kõik kirjed“"},{"title":"Oleku jälgimine","desc":"Vaadake ravi kuupäeva järgi neljal vahekaardil: ootel, manustatud, vahele jäetud, lõpetatud.","alt":"Manustamise kuva, esile tõstetud olekuvahekaardid „manustatud“, „vahele jäetud“, „lõpetatud“, „ootel“"},{"title":"Hulgitoimingud","desc":"Valige mitu kirjet, et ravimid korraga manustada või vahele jätta.","alt":"Manustamise kuva, pärast kirjete valimist esile tõstetud „Vali kõik“ ja nupp „Manusta“ (\"Administer\")"},{"title":"Retsepti üksikasjad","desc":"Näete manustamise hetkel kogu teavet: annus, partii number, seotud loom.","alt":"Retsepti kuva, esile tõstetud kellaajad, sagedus, kestus ja manustamisviis"},{"title":"Üksikannuse sisestamine","desc":"Registreerige üksikannused koos kellaaja, partii numbri ja märkmetega.","alt":"Manustamise kuva, esile tõstetud üksikannuse rühmakaart ja selle märkeruut"},{"title":"Avakuva ülevaade","desc":"Näete ootel ravide arvu otse avakuval, et saaksite kiiremini tegutseda.","alt":"Rakenduse avakuva: peamised näitajad ja ootel manustamiste kaart, millel on 1028 ootel toimingut"}],"shots":{"assets/shots/p20-bulk.png":"Manustamise hulgitoimingud: „Vali kõik“, valitud looma kirje ning nupud „Vahele jäetud“ ja „Manusta“","assets/shots/p20-prescription.png":"Retsepti üksikasjad: juhtumi ID, kellaajad, sagedus, kestus, manustamisviis, seotud loom ja annustamisgraafik"}},"vaccination":{"title":"Vaktsineerimine","intro":"Vaktsineerimise moodul haldab loomade vaktsineerimise kogu elutsüklit alates plaanimisest ja otsesest manustamisest kuni eelseisvate, ootel, vahele jäetud ja tehtud vaktsineerimiste jälgimiseni. See tagab õigeaegse ravi, täpse annuste registreerimise ja täieliku jälgitavuse haiguste ennetamiseks ja kliiniliste nõuete täitmiseks.","summary":"Haldab loomade vaktsineerimise kogu elutsüklit plaanimisest ja otsesest manustamisest kuni eelseisvate, ootel, vahele jäetud ja tehtud vaktsineerimiste jälgimiseni","features":[{"title":"Olekupõhised vaated","desc":"Vaktsineerimised on hõlpsaks jälgimiseks jaotatud: eelseisvad, ootel, vahele jäetud ja tehtud.","alt":"Vaktsineerimise menüü: eelseisvad, ootel, tehtud, vahele jäetud, lõpetatud vaktsiinid, otsene manustamine, vaktsineerimise plaanimine"},{"title":"Vaktsineerimise haldus","desc":"Planeerige vaktsineerimine või registreerige manustatud vaktsiin otse koos kuupäevade ja ravimi andmetega.","alt":"Vaktsineerimise plaanimine valitud loomade, retsepti ja kliiniliste märkmetega"},{"title":"Manustamise registreerimine","desc":"Salvestab annuse, partii numbri, manustamisviisi, märkmed ja valikulise järelkontrolli.","alt":"Tehtud vaktsineerimise üksikasjad juhtumi ID ja partii numbriga"},{"title":"Ootel ja eelseisvad","desc":"Kuvab kõik plaanitud vaktsineerimised kuupäeva ja asukoha järgi, et ükski ravi ei jääks vahele.","alt":"Ootel vaktsineerimised liikide kaupa rühmitatuna"},{"title":"Vahelejätmine ja lõpetamine","desc":"Lükake vaktsineerimisi edasi või lõpetage need kohustusliku põhjuse ja järelkontrolli kuupäevaga.","alt":"Ootel vaktsineerimise üksikasjad toimingutega „Manusta“ ja „Vahele jäetud“"},{"title":"Loomakeskne juurdepääs","desc":"Vaktsineerimiskirjeid saab vaadata loomade, paigutuse või terviseandmete vaates.","alt":"Looma profiili meditsiini vahekaart ootel, eelseisvate ja tehtud vaktsineerimistega"}]},"deworming":{"title":"Ussitõrje","intro":"Ussitõrje moodul toetab parasiiditõrje ravi süstemaatilist registreerimist ja jälgimist, tagades õigeaegse manustamise, nõuetekohase dokumenteerimise ja iga looma kõigi ussitõrjetoimingute selge jälgimise.","summary":"Toetab parasiiditõrje ravi süstemaatilist registreerimist ja jälgimist","features":[{"title":"Olekupõhised vaated","desc":"Ussitõrjed on hõlpsaks jälgimiseks jaotatud: eelseisvad, ootel, vahele jäetud ja tehtud.","alt":"Ussitõrje menüü: eelseisvad, ootel, tehtud, vahele jäetud, lõpetatud ussitõrjed, otsene manustamine, ussitõrje plaanimine"},{"title":"Ussitõrje haldus","desc":"Planeerige ravikuur või registreerige manustatud ravim otse koos kuupäevade ja üksikasjadega.","alt":"Otsene ussitõrje valitud looma, retsepti ja kliiniliste märkmetega"},{"title":"Manustamise registreerimine","desc":"Salvestab annuse, partii numbri, manustamisviisi, märkmed ja valikulise järelkontrolli.","alt":"Ravimi lisamine: annuse tüüp, annuse kogus, manustamisviis, järelkontroll ja partii number"},{"title":"Ootel ja eelseisvad","desc":"Vaadake kõiki plaanitud ussitõrjeid kuupäeva ja asukoha järgi, et ükski ravi ei jääks vahele.","alt":"Ootel ussitõrjed liikide kaupa rühmitatuna"},{"title":"Vahelejätmine ja lõpetamine","desc":"Lükake edasi või lõpetage kohustusliku põhjuse ja järelkontrolli kuupäevaga.","alt":"Ussitõrje vahelejätmine: uus aeg või lõpetamine koos põhjuse ja kõrvaltoimete küsimusega"},{"title":"Loomakeskne juurdepääs","desc":"Vaadatav loomade, paigutuse või terviseandmete vaates.","alt":"Looma profiili meditsiini vahekaart ootel, eelseisvate ja tehtud ussitõrjetega"}]},"supplements":{"title":"Lisandid","intro":"Lisandite moodul toetab toitumis- ja toidulisandiprogrammide süstemaatilist registreerimist ja jälgimist, tagades õigeaegse manustamise, nõuetekohase dokumenteerimise ja iga loomale antud lisandi selge jälgimise.","summary":"Toetab toitumis- ja toidulisandiprogrammide süstemaatilist registreerimist ja jälgimist","features":[{"title":"Olekupõhised vaated","desc":"Lisandid on jaotatud: eelseisvad, ootel, vahele jäetud ja tehtud.","alt":"Lisandite menüü: eelseisvad, ootel, tehtud, vahele jäetud, lõpetatud lisandid, otsene manustamine, lisandite plaanimine"},{"title":"Lisandite haldus","desc":"Planeerige või registreerige manustatud lisandid otse koos kuupäevade ja üksikasjadega.","alt":"Otsesed lisandid valitud looma, retsepti ja kliiniliste märkmetega"},{"title":"Manustamise registreerimine","desc":"Salvestab annuse, partii numbri, manustamisviisi, märkmed ja valikulise järelkontrolli.","alt":"Lisandite lisamine: annuse tüüp, annuse kogus, manustamisviis, järelkontroll ja partii number"},{"title":"Ootel ja eelseisvad","desc":"Kõik plaanitud lisandid kuupäeva ja asukoha järgi, et ükski manustamine ei jääks vahele.","alt":"Ootel lisandid liikide kaupa rühmitatuna"},{"title":"Vahelejätmine ja lõpetamine","desc":"Lükake edasi või lõpetage kohustusliku põhjuse ja järelkontrolli kuupäevaga.","alt":"Lisandite vahelejätmine: uus aeg või lõpetamine koos põhjuse ja järelkontrolli kuupäevaga"},{"title":"Loomakeskne juurdepääs","desc":"Kirjed on vaadatavad loomade, paigutuse või terviseandmete vaates.","alt":"Looma profiili meditsiini vahekaart ootel, eelseisvate ja tehtud lisanditega"}]},"hospital-information-management-system-app":{"title":"Haiglainfosüsteem (App)","intro":"Rakenduses algatavad töötajad loomade üleviimise haiglasse ja viivad patsiendid turvaliselt üle, lisades meditsiinilise ID, visiidi tüübi, eesmärgi ja manused ning tehes asukohas ja haiglas turvakontrolliga sisse- ja väljaregistreerimise.","summary":"Töötajad algatavad loomade üleviimise haiglasse ja viivad patsiendid turvaliselt üle","features":[{"title":"Üleviimistaotlused","desc":"Algatage looma üleviimine aedikust haiglasse koos meditsiinilise ID, visiidi tüübi, eesmärgi ja manustega.","alt":"Looma haiglasse paigutamise vorm: valitud loom, meditsiiniline ID (loo uus), haigla ja visiidi tüübi väljad, esita"},{"title":"Üleviimise olek","desc":"Jälgige iga üleviimise etappe: ootel, teel, vastu võetud.","alt":"Üleviimine HT29-00038: marsruut, algataja, valitud loom, olek „Üleviimine lõpetatud“ ja turvakontrolliga väljaregistreerimise nupp"},{"title":"Turvakontrolliga sisse- ja väljaregistreerimine","desc":"Patsientide kontrollitud liikumine turvakontrolliga sisse- ja väljaregistreerimisega asukohas ja haiglas.","alt":"Üleviimine HT29-00038: marsruut, algataja, valitud loom, olek „Üleviimine lõpetatud“ ja turvakontrolliga väljaregistreerimise nupp"},{"title":"Väljakirjutamise aruannete vaatamine","desc":"Avage väljakirjutamise kokkuvõtted ja haiglaravi ajalugu otse rakendusest.","alt":"Looma haiglasse paigutamise vorm: valitud loom, meditsiiniline ID (loo uus), haigla ja visiidi tüübi väljad, esita"}]},"hospital-information-management-system-web":{"title":"Haiglainfosüsteem (Web)","intro":"Veebikonsoolis võtavad kliinilised meeskonnad saabuvad patsiendid vastu ja teevad triaaži, jälgivad statsionaarseid ja ambulatoorseid patsiente, registreerivad ravi ja kirjutavad loomad välja, tagades täieliku meditsiinilise jälgitavuse ja allalaaditavad aruanded.","summary":"Kliinilised meeskonnad võtavad saabuvad patsiendid vastu ja teevad triaaži, jälgivad statsionaarseid ja ambulatoorseid patsiente, registreerivad ravi ja kirjutavad loomad välja","features":[{"title":"Vastuvõtt ja triaaž","desc":"Võtke looma juhtum vastu või lükake tagasi ning määrake ravivajaduse põhjal arst, ruum ja koht.","alt":"Patsiendi vastuvõtu vorm: valitud loom, visiidi eesmärk, ravi tüüp ambulatoorne / statsionaarne, tervislik seisund, „Lükka tagasi“ ja „Võta vastu“"},{"title":"Statsionaarsete / ambulatoorsete patsientide jälgimine","desc":"Seadistage ja registreerige plaanilised elutähtsad näitajad ja vaatlused muudetavate ajatelgedega.","alt":"Saabuvate patsientide loend: ootel ja tagasi lükatud vahekaardid loomade ja visiidi eesmärgiga"},{"title":"Kliinilised ja raviandmed","desc":"Hoidke sümptomid, kliinilised märkmed, retseptid, anesteesia, operatsioonid ja muu ravi ühes kohas.","alt":"Statsionaarse patsiendi kirje MED29-17409: vastuvõtu üksikasjad ning sümptomite, kliinilise hindamise ja retsepti vahekaardid"},{"title":"Väljakirjutamine","desc":"Kirjutage loomad välja tagasi aedikusse või registreerige surm koos lahangutaotluse ja manustega.","alt":"Väljakirjutamise vahekaart: vastuvõtu põhjus, väljakirjutamise tüüp surm / üleviimine aedikusse, looma väljakirjutamine"},{"title":"Allalaaditavad aruanded","desc":"Avage väljakirjutamise kokkuvõtted, praeguse haiglaravi andmed ja varasemate visiitide ajalugu.","alt":"Välja kirjutatud patsientide loend kestuse, visiidi tüübi, peaveterinaari ja allalaadimise toiminguga"}]},"mortality":{"title":"Suremus","intro":"Suremuse moodul võimaldab loomade surmajuhtumeid kiiresti ja täpselt registreerida, hallata lahangu andmeid ja hoida tõendeid ühes kohas. See suurendab läbipaistvust, kiirendab otsuste tegemist, tagab nõuetele vastavuse ja toetab loomade heaolu paremat jälgimist.","summary":"Võimaldab loomade surmajuhtumeid kiiresti ja täpselt registreerida, hallata lahangu andmeid ja hoida tõendeid ühes kohas","features":[{"title":"Suremuse töölaud","desc":"Surmajuhtumite, mõjutatud liikide ja põhjuste koguarvud.","alt":"Suremuse töölaud: 2 looma, 2 liiki, 2 põhjust"},{"title":"Mitu loendivaadet","desc":"Kirjed looma, liigi või põhjuse järgi, seotud profiilidega.","alt":"Suremuse kirjed loomade kaupa"},{"title":"Täpsem otsing ja filtrid","desc":"Otsige liigi, põhjuse, asukoha, kuupäeva või märksõna järgi.","alt":"Suremuse otsing ja filtrid"},{"title":"Surnud loomade kirjed","desc":"Surma täielikud andmed: põhjus, ID, aedik, asukoht, sugu.","alt":"Surnud looma kirje üksikasjad"},{"title":"Kirjete muutmine","desc":"Muutke suremusaruandeid pärast sisestamist, et need püsiksid täpsed.","alt":"Suremusaruande üksikasjad muutmisvalikuga"},{"title":"Kirjete tühistamine","desc":"Tühistage ekslikud kirjed, et taastada looma aktiivne olek.","alt":"Suremusaruanne valikuga „Tühista surm“ (\"Revoke Mortality\")"},{"title":"Korjuste üleviimine","desc":"Vaadake ja jälgige korjuste liikumist asukohtade vahel.","alt":"Korjuste üleviimiste loend: ootel, teel, lõpetatud"}],"shots":{"assets/shots/p27-mortality-4.jpg":"Suremuskirje kaart – muutmine ja tühistamine"}},"necropsy":{"title":"Lahang","intro":"Lahangu moodul dokumenteerib surmajärgsed uuringud koos üksikasjalike tähelepanekute, elundipõhiste leidude ja meditsiiniliste järeldustega. See toetab surmapõhjuse täpset analüüsi, ühtlustab aruandlust, tagab korjuste õigeaegse käitlemise ning vastab õigus-, auditi- ja veterinaarnõuetele.","summary":"Dokumenteerib surmajärgsed uuringud koos üksikasjalike tähelepanekute, elundipõhiste leidude ja meditsiiniliste järeldustega","features":[{"title":"Otsing ja filtrid","desc":"Otsige looma/liigi järgi; filtreerige asukoha, kuupäeva ja prioriteedi järgi.","alt":"Lahangute loend: saabuvad, ootel, mustandid, lõpetatud, taotluste kaartidega"},{"title":"Oleku jälgimine","desc":"Jälgige etappe: saabuvad, ootel, mustand ja lõpetatud.","alt":"Lahangute loend olekuvahekaartidega: saabuvad, ootel, mustand, lõpetatud"},{"title":"Looma kaart ja taotluse teave","desc":"AID, liik, asukoht, põhjus, taotleja, prioriteet.","alt":"Lahangute loend loomade kaupa koos taotluse kaardi üksikasjadega"},{"title":"Korjuste üleviimine","desc":"Vaadake üleviimistaotlusi: ootab vastuvõtmist, vastu võetud.","alt":"Korjuste üleviimiste loend: ootab vastuvõtmist, vastu võetud"},{"title":"Taotluse üksikasjalik vaade","desc":"Vaadake kogu lahangutaotlust koos looma ja surma andmetega (põhjus, korjuse seisund, märkmed), uuendage kirjeid, salvestage mustandina või esitage lõplikult.","alt":"Lahangutaotluse üksikasjad: suremusaruanne, põhjus, korjuse seisund, olek"},{"title":"Aruande allalaadimine","desc":"Eksportige aruanded või mustandid PDF-failidena arhiveerimiseks või võrguühenduseta kasutamiseks.","alt":"Lahanguaruanne NPS29-00034 allalaadimisega – korjuse sobivus ja üksikasjad"},{"title":"Ajatelg","desc":"Iga toiming salvestatakse koos kasutaja ja ajatempliga.","alt":"Lahangu ajaloo ajatelg: lahangu lõpetas Mayur Bendre"}]},"fetal-death":{"title":"Loote surm","intro":"Loote surma moodul registreerib ja haldab aedikutes toimunud loote surma juhtumeid, salvestades põhjuse, aja ja seotud loomade andmed. See toetab veterinaarravi, sigimistervise jälgimist, suundumuste analüüsi ja paremat populatsiooni haldamist.","summary":"Registreerib ja haldab aedikutes toimunud loote surma juhtumeid","features":[{"title":"Loote surma kirje lisamine","desc":"Sisestage uued juhtumid: põhjus, aeg, põlvnemine, looma andmed.","alt":"Loote surma lisamise vorm aediku, liigi ja vanemaga"},{"title":"Otsing ja filtrid","desc":"Otsige märksõna järgi; filtreerige asukoha, kuupäeva, surnultsünni või abordi, liigi või soo järgi.","alt":"Loote surmade loend otsingu ja filtriga"},{"title":"Surmajuhtumite kirjete vaatamine","desc":"Täielikud andmed, surmast möödunud päevad, põhjus, ID, aedik, asukoht, sugu.","alt":"Loote surmade kirjete loend, surnultsündide vahekaart"},{"title":"Looma kaardi kuvamine","desc":"FID, liik, leidmine, vanemad, asukoht, sugu, teataja.","alt":"Loote surma kokkuvõtte kaart"},{"title":"Kirje muutmine","desc":"Muutke olemasolevat kirjet kokkuvõttest, auditijäljega.","alt":"Loote surma kokkuvõte muutmispliiatsiga"},{"title":"Kirje kustutamine","desc":"Eemaldage kirje vajaduse korral, täieliku auditijäljega.","alt":"Loote surma kokkuvõte valikuga „Kustuta loote surm“ (\"Delete Fetal Death\")"}]},"egg-management-app":{"title":"Munade haldus — App","intro":"Munade moodul jälgib munade kogu elutsüklit munemisest koorumise või kasvandusse üleviimiseni, tagades täpsed andmed, reaalajas värskendused ja täieliku jälgitavuse, et pesa-, kasvanduse- ja haudemeeskondade koostöö ja vastutus oleksid paremad.","summary":"Jälgib munade kogu elutsüklit","features":[{"title":"Munade töölaud","desc":"Reaalajas arvud: pesas, kasvandusse viidud, hävitamiseks märgitud.","alt":"Munade kogumise töölaud: 66 pesas, 76 kasvandusse, 35 hävitamiseks"},{"title":"Munade sisestamine (pesa / kasvandus)","desc":"Lisage munad koos vanemate, seisundi, kuupäevade, liigi, märkmete ja manustega.","alt":"Munade lisamise vorm aediku, põlvnemise ja muna asukohaga"},{"title":"Elutsükli jälgimine","desc":"Olek, kaal ja muna teekonna täielik ajatelg.","alt":"Muna teekonna ajatelg: koorunud, looduslik haudumine"},{"title":"Looduslik haudumine","desc":"Pesas hautavad munad: ID, kogumise kuupäev, seisund.","alt":"Pesas olevate munade loend emase paabulinnu kirjetega"},{"title":"Kunstlik haudumine","desc":"Kasvanduse munad: hindamine, inkubaatorisse viimine, hävitamine või koorumine.","alt":"Kasvandusse viidud munade loend"},{"title":"Munade üleviimine","desc":"Jälgige asukohta, etappi, koorumise kuupäeva, liiki, ID-d ja sugu.","alt":"Üle viidud munad – partii üleviimistaotlused"},{"title":"Munade hävitamine","desc":"Hävitage elujõuetud munad, põhjus ja auditijälg salvestatakse.","alt":"Hävitatavate munade loend"},{"title":"Looma ID loomine","desc":"Looge koorunud munale kirje, mis on seotud liigi ja vanematega.","alt":"Koorunud munad – looma ID loomine"}]},"egg-management-web":{"title":"Munade haldus — Web","intro":"Munade halduse veebiversioon, mida kasutavad juhendajad ja kasvanduse juhid inkubaatorite seadistamiseks, aruannete koostamiseks ja munade jälgimiseks elutsükli igas etapis. Täielik jälgitavus, filtreeritavad vaated ja eksporditavad aruanded nõuetele vastavuse ja ülevaatuse jaoks.","summary":"Juhendajad ja kasvanduse juhid kasutavad seda inkubaatorite seadistamiseks, aruannete koostamiseks ja munade jälgimiseks elutsükli igas etapis","features":[{"title":"Kasvanduse ja inkubaatorite seadistus","desc":"Seadistage asukohtadega seotud kasvandused, looge ruume, hallake inkubaatoreid.","alt":"Kasvanduste loend ruumide, inkubaatorite ja asukohtadega"},{"title":"Aruandlus, filtrid ja juurdepääs andmetele","desc":"Filtreerige asukoha, liigi, kuupäeva või etapi järgi; eksportige aruandeid.","alt":"Munade statistika tabel liikide kaupa"},{"title":"Munade loend","desc":"Olekupõhised vahekaardid: vastu võetud, haudumisel, koorunud, hävitatud, kõik.","alt":"Munade loend vahekaartidega vastu võetud, haudumisel, koorunud"}]},"announcement":{"title":"Teadaanded","intro":"Teadaannete moodul on keskne tööriist oluliste uudiste ja üldiste teadete jagamiseks meeskondade ja asukohtade vahel. See toetab sihitud suhtlust, ajastamist ja interaktiivset kaasamist, et õige sõnum jõuaks õigel ajal õigete inimesteni.","summary":"Keskne tööriist oluliste uudiste ja üldiste teadete jagamiseks meeskondade ja asukohtade vahel","features":[{"title":"Teadaannete tüübid","desc":"Üldised ja olulised, kummalgi oma nähtavusreeglid.","alt":"Teadaannete loend vahekaartidega „Kõik“ ja „Minu loodud“, oluliste teadete ja teadaannete kaardid"},{"title":"Ühtne loend","desc":"Kõik teadaanded ühes vaates, Teie omad teistest eraldi.","alt":"Teadaande üksikasjad: Every Move Counts koos lisatud pildiga"},{"title":"Teadaannete loomine","desc":"Määrake tüüp, pealkiri ja nähtavus; avaldage kohe või ajastage; eelvaade ja manused.","alt":"Teadaande üksikasjad: Every necropsy counts, loomise nupuga"},{"title":"Toimingud pärast avaldamist","desc":"Muutke, tühistage või kustutage teadaandeid. Teavitused ja avaleht hoiavad need õigetele inimestele nähtaval.","alt":"Üldise teadaande üksikasjad avatud menüüga: muuda, tühista, kustuta"}]},"helpdesk-module":{"title":"Kasutajatoe moodul","intro":"Taotluste moodul aitab loomaaia töötajatel esitada ja jälgida ressursside, hoolduse või teenuste taotlusi, tagades vastutuse, kiirema lahenduse ja parema koostöö osakondade vahel. See asendab e-kirjad ja paberil taotlused ühtse, auditeeritava jäljega.","summary":"Aitab loomaaia töötajatel esitada ja jälgida ressursside, hoolduse või teenuste taotlusi, tagades vastutuse, kiirema lahenduse ja parema koostöö osakondade vahel","features":[{"title":"Taotluste vaatamine oleku järgi","desc":"Ootel, kinnitatud, tagasi lükatud, tühistatud, töös, lõpetatud.","alt":"Kasutajatoe loend vahekaartidega: ootab kinnitamist, kinnitatud, tagasi lükatud, tühistatud"},{"title":"Taotluste haldus","desc":"Esitage, muutke, tühistage või lükake tagasi prioriteetidega taotlusi.","alt":"Puusepatöö taotluse üksikasjad tarnija ja kulude hinnanguga"},{"title":"Kulude haldus","desc":"Lisage, muutke, dubleerige või kustutage iga üksuse kulude hinnanguid.","alt":"Kulude jaotus: katusetööde ja puidu read"},{"title":"Täitmine ja tagasipööramine","desc":"Märkige taotlused täidetuks või viige need tagasi olekusse „töös“.","alt":"Lõpetatud taotlus valikuga „Tagasi olekusse Töös“ (\"Move Back To In-Progress\")"}]},"security":{"title":"Turvalisus","intro":"Turvamoodul haldab asukohapõhiseid õigusi ning jälgib munade üleviimise ja hävitamise protsesse ning kõiki loomade ja haiglasse üleviimisi, et tagada kontrollitud liikumine ja täielik vastutus selle eest, kes mida ja millal käsitles.","summary":"Haldab asukohapõhiseid õigusi ning jälgib munade üleviimist ja hävitamist ning kõiki loomade ja haiglasse üleviimisi","features":[{"title":"Filtreerimine","desc":"Filtreerige kirjeid oleku järgi – kõik, väljaregistreerimine ootel või turvakontroll läbitud –, et ülevaatus oleks fookuses.","alt":"Filtreerimise dialoog: kõik, väljaregistreerimine ootel, turvakontroll läbitud"},{"title":"Sisse- ja väljaregistreerimine","desc":"Volitatud turvatöötajad teevad munade, loomade ja haiglasse üleviimiste sisse- ja väljaregistreerimise.","alt":"Üleviimine INT-02997 turvakontrolliga väljaregistreerimise nupuga"}]},"reports-app":{"title":"Aruanded - App","intro":"Aruannete moodul esitab peamiste loomadega seotud sündmuste andmed kategooriate kaupa kindlate pealkirjade all, et saaksite liikvel olles kiire ülevaate ja analüüsi.","summary":"Esitab peamiste loomadega seotud sündmuste andmed kategooriate kaupa kiireks ülevaateks ja analüüsiks liikvel olles","features":[{"title":"Filtrid","desc":"Täpsustage aruandeid kuupäeva, asukoha või liigi järgi.","alt":"Peamiste näitajate aruanne: päeva/nädala/kuu filter, kuupäev, sündimus ja jaotus liikide kaupa"},{"title":"Statistika","desc":"Kuupäevapõhine filtreerimine ja statistika kategooriate kaupa: sündimus, suremus, uued saabujad, asukohtadevahelised üleviimised (sisse/välja), välised ja asutusesisesed üleviimised ning toidujäätmed.","alt":"Statistika kategooria valik: sündimus, suremus, uued saabujad, asukohtadevahelised üleviimised, väline üleviimine"}]},"reports-web":{"title":"Aruanded (Web)","intro":"Veebiversioon koostab loomade andmete ja tegevuste kohta hõlpsasti loetavaid ja allalaaditavaid aruandeid, mis hõlmavad sünde, surmajuhtumeid, üleviimisi ja hindamisi ning põhinevad samadel andmetel kui rakendus.","summary":"Koostab loomade andmete ja tegevuste kohta hõlpsasti loetavaid ja allalaaditavaid aruandeid","features":[{"title":"Filtrid ja otsing","desc":"Täpsustage aruandeid kuupäeva, asukoha või liigi järgi.","alt":"Liikide üldaruanne: aruande allalaadimine, asukoha valik ja filtrite kuvamine/peitmine ning liikide tabel isaste, emaste, määramata ja määramatu soo arvuga"},{"title":"Allalaaditavad aruanded","desc":"Koostage, vaadake ja laadige alla liikide, päeva-, loomade loendi, loomade hindamise, loomahoidjate, kasutajate, vaatluste, hoidjapäeviku, bioloogipäeviku ja aedikute loenduse aruandeid nõuetele vastavuse ja võrguühenduseta kasutamise jaoks.","alt":"Liikide üldaruanne: aruande allalaadimine, asukoha valik ja filtrite kuvamine/peitmine ning liikide tabel isaste, emaste, määramata ja määramatu soo arvuga"}]},"lab":{"title":"Labor","intro":"Labori moodul koondab diagnostiliste testide kirjed ja tulemused, lihtsustab veterinaaride ja laborite vahelisi töövooge, toetab haiguste varajast avastamist ja ravi ning pakub turvalist digitaalset hoidlat bioturvalisuse, auditite ja analüüsi jaoks.","summary":"Koondab diagnostiliste testide kirjed ja tulemused, lihtsustab veterinaaride ja laborite koostööd, toetab haiguste varajast avastamist ning pakub turvalist digitaalset hoidlat","features":[{"title":"Taotluste loend ja filtreerimine","desc":"Vaadake ja filtreerige laboritaotlusi labori, otsingu või oleku järgi – ootel, töös, lõpetatud – värvikoodiga ikoonidega.","alt":"Teadlane töötab mikroskoobiga."},{"title":"Taotluse üksikasjalik vaade","desc":"Näete taotlejat, looma, asukohta ja seotud tervisekirjet; uuendage olekut reaalajas, automaatse sünkroonimisega moodulite vahel.","alt":""},{"title":"Asukoht ja juurdepääsu kontroll","desc":"Märkige laborid asukoha järgi; määrake, kes saab labori andmeid seadistada või vaadata.","alt":""},{"title":"Testide sidumine asukoha tasandil","desc":"Määrake laborid konkreetsetele diagnostilistele testidele otse asukoha seadistuste vahekaardil.","alt":""},{"title":"Üksik- ja hulgimääramine","desc":"Siduge laborid testide kaupa või määrake kõik testid ühe klõpsuga vaikelaborile.","alt":""},{"title":"Testide ja proovide haldus","desc":"Looge ja hallake laboriteste, alamteste ja proovitüüpe (seerum, liikvor jne) ning siduge need õigete laboritega.","alt":""},{"title":"Labori oleku uuendamine","desc":"Jälgige etappe: ootab proovi → proov vastu võetud / tagasi lükatud / hüübinud / hemolüüsunud / ebapiisav → töös → lõpetatud (positiivne / negatiivne / tuvastatud / tuvastamata / ebaselge).","alt":""},{"title":"Labori ümbermääramine","desc":"Viige testid vajaduse korral teise laborisse ilma töövoogu häirimata.","alt":""}]},"diet":{"title":"Toitumine","intro":"Toitumise moodul on keskne platvorm loomade toiduratsioonide tõhusaks planeerimiseks ja haldamiseks. See võimaldab toitumismeeskondadel koostada struktureeritud toitumiskavasid seadistatavatest komponentidest, koostisosadest, söödatüüpidest, retseptidest ja kombinatsioonidest ning ajastada toidukordi kellaaja, päeva või elujärgu järgi.","summary":"Keskne platvorm loomade toiduratsioonide tõhusaks planeerimiseks ja haldamiseks","features":[{"title":"Toiduratsioonide seadistus","desc":"Koostage ratsioone söödatüüpidest, toiduainetest, retseptidest ja segudest; ajastage toidukordi kellaaja, päeva või elujärgu järgi; määrake liigile või üksikloomale; aktiveerige, kloonige või määrake ratsioone; lisage viiteid.","alt":"Loomasöödaks valmistatud värskete puuviljade valik."},{"title":"Valmistusviisid ja tükisuurus","desc":"Looge ja hallake toiduainete, retseptide ja kombinatsioonide valmistusviise, et tagada ühtlane toiteväärtus ja tekstuur.","alt":""},{"title":"Söödatüübid","desc":"Söödakategooriate keskne ja otsitav loend ühtseks toitumise planeerimiseks.","alt":""},{"title":"Toiduained","desc":"Lisage, muutke ja kustutage toidukomponente koos üksikasjalike kirjelduste ja piltidega.","alt":""},{"title":"Retseptid ja segud","desc":"Mitmest koostisosast retseptid ja segud – retseptid kindlate koguste, segud toiduainete protsendi järgi – korduvkasutatavate komponentide ja täieliku tegevuslogiga.","alt":""},{"title":"Söötmisrühmad","desc":"Rühmitage aedikuid kooskõlastatud söötmisgraafikute ja ratsioonide määramise jaoks, filtreerides asukoha, sektsiooni ja liigi järgi.","alt":""}]},"pharmacy-app":{"title":"Apteek (App)","intro":"Võimaldab meditsiinitooteid kiiresti, täpselt ja jälgitavalt väljastada otse volitatud arstidele, tagades õigeaegse täitmise ja laoseisu automaatse uuendamise.","summary":"Võimaldab meditsiinitooteid kiiresti, täpselt ja jälgitavalt väljastada otse volitatud arstidele","features":[{"title":"Taotlemine rakenduses","desc":"Kasutajad saavad tooteid apteegist taotleda otse rakenduse kaudu.","alt":"Väljastuste loend: 11 väljastust taotluse ID, apteegi, kuupäeva, taotleja, ravimi ja koguhulgaga ning nupp „Uus väljastus“"},{"title":"Väljastamine rakenduses","desc":"Ladu saab tooteid apteegist väljastada otse rakenduse kaudu.","alt":"Väljastuse DIS279 üksikasjad: Local Pharmacy, väljastatud kasutajale Antz Admin, üks ravim Crocin koguhulgaga 100"}]},"pharmacy-web":{"title":"Apteek (Web)","intro":"Võimaldab meditsiinitooteid kiiresti, täpselt ja jälgitavalt väljastada otse volitatud arstidele, tagades õigeaegse täitmise ja laoseisu automaatse uuendamise retseptist kuni riiulini ning partiitasandi nähtavuse ja aegumise jälgimise kogu protsessi vältel.","summary":"Võimaldab meditsiinitooteid kiiresti, täpselt ja jälgitavalt väljastada otse volitatud arstidele","features":[{"title":"Töölaud","desc":"Reaalajas ülevaade laoprobleemidest, saadetistest, ostudest, taotlustest, kasutusest, aeguvatest ja kiiresti liikuvatest toodetest koos visuaalsete suundumustega kiireks tegutsemiseks.","alt":"Proviisor korrastab ravimiriiuleid."},{"title":"Nutikas otsing ja filtrid","desc":"Leidke kirjed kiiresti taotluse ID, arsti nime või apteegi järgi.","alt":""},{"title":"Põhiandmed (riiulid ja riiulikohad)","desc":"Korraldage hoiustamine riiulite ja riiulikohtade arvu järgi kiireks juurdepääsuks ja uuendamiseks, kohandatavate andmetega (pakend, mõõtühik, soolad, toimeained, tootjad).","alt":""},{"title":"Laoaruannete haldus","desc":"Partiipõhine laoseis koos väärtuse ja aegumisega; märkige vähese varuga või aegunud tooted; jälgige eelseisvaid aegumisi; hallake deposiiti koos vaidluste lahendamisega.","alt":""},{"title":"Toodete ja laovarude haldus","desc":"Looge tooteid, jälgige laovarusid ja aegumist, registreerige oste ja väljastusi, pidage ühtset pearaamatut, hallake asendustooteid ja variante.","alt":""},{"title":"Väljastamise haldus","desc":"Arstid saavad ravimeid välja kirjutada ja väljastada või need otse apteegist kätte saada, kõik logitakse.","alt":""},{"title":"Saadetiste haldus","desc":"Jälgige sissetulevaid ja väljaminevaid ravimisaadetisi ja täitke need rakenduses.","alt":""},{"title":"Laokorrektsioonid ja aruanded","desc":"Registreerige laoseisu muutused (puuduvad, purunenud, aegunud); säilitage auditi ajalugu; hallake tarnijale tagastusi; laadige alla tarbimise, tagastuste, ostude ja väljastuste aruanded rahanduse ja nõudluse planeerimiseks.","alt":""}]},"compliance":{"title":"Vastavus nõuetele","intro":"Vastavuse moodul annab rakenduses organisatsiooni tasandi ülevaate loomade haldusest mitmes varjupaigas, sihtasutuses ja fondis ning võimaldab kasutajatel avada ekspordi, impordi, saadetiste ja liikide kirjeid, hoides kõik regulatiivsed dokumendid ühes usaldusväärses ja allalaaditavas kohas.","summary":"Annab rakenduses organisatsiooni tasandi ülevaate loomade haldusest mitmes varjupaigas, sihtasutuses ja fondis ning juurdepääsu ekspordi, impordi, saadetiste ja liikide kirjetele","features":[{"title":"Organisatsioonide ülevaade","desc":"Kõik süsteemis registreeritud organisatsioonid ühes vaates.","alt":"Mitme rajatisega looduskaitseala."},{"title":"Liikide ja loomade arv","desc":"Iga organisatsiooni liikide arv ja loomade koguarv.","alt":""},{"title":"Asukohtade katvus","desc":"Iga organisatsiooni all loomi haldavate asukohtade arv.","alt":""},{"title":"Läbipaistvus ja vastutus","desc":"Täpne aruandlus ja ülevaade loomapopulatsioonidest organisatsioonide lõikes.","alt":""},{"title":"Filtrid ja allalaadimine","desc":"Filtreerige ja laadige alla dokumente valitud kuupäevavahemiku põhjal.","alt":""},{"title":"Eksport ja import","desc":"Sisestage ja muutke lubade vorme loomadele, keda eksporditakse teise riiki või asutusse või imporditakse sealt.","alt":""},{"title":"Saadetised","desc":"Jälgige saadetise üksikasju, transpordiviisi, saatmise kuupäeva, konteinereid ja logistikat.","alt":""},{"title":"Liigid","desc":"Vaadake ja laadige alla teavet tehinguga seotud liikide kohta (linnud, imetajad, roomajad).","alt":""},{"title":"Põhiandmete seadistus","desc":"Seadistage dokumenditüübid ja pidage ekspordi-/impordikirjete jaoks importijate ja eksportijate loendeid.","alt":""}]}}};
